# Conteúdo de linguagem com critérios de dificuldade explícitos.
import random as _sorteio_linguagem

def _adicionar_linguagem(codigo, faixa, nivel, habilidade, familia, texto, alternativas, correta, explicacao):
    alternativas = list(dict.fromkeys(alternativas))
    if len(alternativas) != 4 or correta not in alternativas:
        raise ValueError(f"Alternativas inválidas: {codigo}")
    _sorteio_linguagem.Random(codigo).shuffle(alternativas)
    q = _q(codigo,nivel,habilidade,familia,texto,alternativas,correta,
        ["Releia a frase ou o trecho apresentado.", "Compare o que cada opção afirma com as informações do texto.", explicacao],explicacao,faixa)
    q.update(versao=3, familia=familia, assinatura="linguagem:"+texto)
    QUESTOES.append(q)

