# Quatro revisões distintas evitam tratar só a troca de horário como novidade.
for _qv in QUESTOES:
    if _qv["id"].startswith("por-v3-revisao5-"):
        _idx=int(_qv["id"].split("-")[-2]);_j=int(_qv["id"].split("-")[-1]);_suj,_verb,_comp,_sing,_fut=_FRASES_REVISAO[_idx]
        _base=f"{_suj} {_verb} {_comp}."
        if _j==0:
            _pergunta="Qual revisão mantém a ação no passado, a concordância e uma conclusão limitada?"
            _correta=_base+" O resultado observado não comprova uma regra para todos os grupos."
            _erradas=[f"{_suj} {_sing} {_comp}, portanto todos terão o mesmo resultado.",f"{_suj} {_fut} {_comp}, ontem.",_base+" Logo, nenhuma nova observação será necessária."]
        elif _j==1:
            _pergunta="Acrescente a ação posterior sem deixar dúvida sobre quem apresentou o relatório. Qual versão é mais clara?"
            _correta=_base+f" Depois, os representantes de {_suj.lower()} apresentaram o relatório à direção."
            _erradas=[_base+" Depois, eles disseram a eles que eles tinham apresentado o relatório.",_base+" O relatório foi apresentado antes da ação que o texto chama de posterior.",f"{_suj} {_sing} {_comp}. Depois, os representantes apresentou o relatório."]
        elif _j==2:
            _pergunta="Qual continuação distingue observação de explicação, sem afirmar uma causa não investigada?"
            _correta=_base+" A mudança coincidiu com outro resultado, mas essa coincidência não basta para explicar sua causa."
            _erradas=[_base+" A ordem dos acontecimentos comprova, sozinha, a única causa possível.",_base+" Como um fato ocorreu depois do outro, nenhuma outra explicação pode ser examinada.",_base+" Sem investigar outros fatores, já se demonstrou a causa exclusiva."]
        else:
            _pergunta="Qual versão integra uma dificuldade e a continuidade da ação com um conectivo de oposição adequado?"
            _correta=f"Embora houvesse dúvidas, {_suj.lower()} {_verb} {_comp}."
            _erradas=[f"Porque não havia nenhuma dúvida, {_suj.lower()} {_verb} {_comp}.",f"Embora houvesse dúvidas, {_suj.lower()} {_sing} {_comp}.",f"Embora houvesse dúvidas, {_suj.lower()} não realizou a ação, que o texto afirma ter concluído."]
        _qv["enunciado"]=_base+" "+_pergunta
        _qv["correta"]=_correta;_qv["alternativas"]=[_correta]+_erradas
        _sorteio_linguagem.Random(_qv["id"]).shuffle(_qv["alternativas"])
        _qv["familia"]=("revisao_concordancia","revisao_referencia","revisao_causalidade","revisao_oposicao")[_j]
        _qv["assinatura"]=_qv["familia"]+":"+_base
        _qv["explicacao"]="A opção atende ao critério solicitado sem alterar a ação ou acrescentar uma conclusão não sustentada."
        _qv["dicas"]=["Confira os fatos da frase inicial.","Observe o critério pedido: tempo, referência, causa ou oposição.",_correta]
    elif _qv["id"].startswith("por-v3-conc4-"):
        _idx=int(_qv["id"].split("-")[-2]);_j=int(_qv["id"].split("-")[-1]);_suj=_FRASES_REVISAO[_idx][0].lower()
        _nucleo,_verbo,_errado,_fim=[("A participação","foi","foram","importante"),("O relatório","estava","estavam","completo"),("Os registros","foram","foi","conferidos"),("Cada representante","estava","estavam","presente")][_j]
        _correta=f"{_nucleo} de {_suj} {_verbo} {_fim}."
        _qv["enunciado"]=f"Qual frase faz o verbo concordar com o núcleo '{_nucleo}', apesar da expressão plural que vem depois?"
